INSERT INTO `wp_comments` VALUES (1,1,'Komentator WordPressa','wapuu@wordpress.example','https://pl.wordpress.org/','','2025-03-10 14:43:11','2025-03-10 13:43:11','Cześć, to jest komentarz.\nAby zapoznać się z moderowaniem, edycją i usuwaniem komentarzy, należy odwiedzić ekran komentarzy w kokpicie.\nAwatary komentujących pochodzą z <a href=\"https://pl.gravatar.com/\">Gravatara</a>.',0,'1','','comment',0,0);
